/bin/bash -c "python3 - <<'PY'
from math import sin,pi,sqrt
step=0.002
lo=-3.5
N=3001
xs=[lo+i*step for i in range(N)]
def t(x,c): return max(0.0,1-abs(x-c)/0.04)
def g0(x): return t(x,0.4)+2*t(x,0.6)
def g1(x): return g0(1-x)
def a(x):
    if x>=0: return 1-x
    if x<=-2: return x+3
    return 1+(2/pi)*sin(pi*(x+2)/2)
def records(fn): return {i:fn(x) for i,x in enumerate(xs) if fn(x)>1e-10}
F=[records(g0),records(lambda x:g0(a(x)))]
G=[records(g1),records(lambda x:g1(a(x)))]
norm=lambda r:sum(v*v for v in r.values())
def distance(A,B,base):
    answers=[]
    for i,p in enumerate(A):
        for j,q in enumerate(B):
            correlations={}
            for u,pu in p.items():
                for v,qv in q.items():
                    s=u-v
                    correlations[s]=correlations.get(s,0)+pu*qv
            corr=max(correlations.values())
            answers.append((i,j,sqrt(max(0,norm(q)-corr*corr/norm(p))/norm(base))))
    return answers
print('Global separation candidates D(f0,f1):',distance(F,G,G[0]))
print('Global separation candidates D(f1,f0):',distance(G,F,F[0]))
print('Maximum observed-domain mismatch g0 vs g1 o A:',max(abs(g0(i/1000)-g1(a(i/1000))) for i in range(1001)))
print('Maximum observed-domain mismatch g1 vs g0 o A:',max(abs(g1(i/1000)-g0(a(i/1000))) for i in range(1001)))
print('Under a uniform deformation choice, both classes have the same observed-image distribution.')
PY"
